changeSet.sql:
update file_upload fu set entity_type = 'COMPANY', entity_id=c.id from company c where c.logo_id = fu.id;
update file_upload fu set entity_type = 'USER', entity_id=u.id from users u where u.image_id = fu.id;
update file_upload fu set entity_type = 'TERMINAL_LOG', entity_id=tl.id from terminal_log tl where tl.db_file_id = fu.id;
update file_upload fu set entity_type = 'OFD_APPLICATION', entity_id=oa.id from ofd_application oa where oa.file_id = fu.id;
update file_upload fu set entity_type = 'COMPANY_AGREEMENT', entity_id=ca.id from company_agreement ca where ca.file_id = fu.id;
update file_upload fu set entity_type = 'RECEIPT_TEMPLATE', entity_id=rt.id from receipt_template rt where rt.footer_id = fu.id;
update file_upload fu set entity_type = 'RECEIPT_TEMPLATE', entity_id=rt.id from receipt_template rt where rt.header_id = fu.id;
update file_upload fu set entity_type = 'TERMINAL_TRANSFER', entity_id=tt.id from terminal_transfer tt where tt.file_id = fu.id;
update file_upload fu set entity_type='BILL_ACT', entity_id=b.id from bill b where fu.id = b.act_id;
update file_upload fu set entity_type='BILL_AGREEMENT', entity_id=b.id from bill b where fu.id = b.agreement_id;
update file_upload fu set entity_type='BILL_HUMO_REQUEST', entity_id=b.id from bill b where fu.id = b.humo_request_id;
update file_upload fu set entity_type='BILL_HUMO_CONTRACT', entity_id=b.id from bill b where fu.id = b.humo_contract_id;
